def _get_gitlab_headers():
    token = os.environ.get(GITLAB_TOKEN_ENV, None)
    headers = {}
    if token:
        headers["PRIVATE-TOKEN"] = token
    return headers


def _get_project_id():
    try:
        if oas_common and hasattr(oas_common, "get_gitlab_project_id"):
            return oas_common.get_gitlab_project_id("ledger-api")
    except Exception:
        pass
    try:
        resp = requests.get(
            f"{GITLAB_URL}/api/v4/projects",
            params={"search": "ledger-api"},
            headers=_get_gitlab_headers(),
            timeout=10,
        )
        if resp.status_code == 200:
            data = resp.json()
            for p in data:
                if p.get("name") == "ledger-api" or p.get("path") == "ledger-api":
                    return p.get("id")
    except Exception:
        return None
    return None


def _get_project_members(project_id):
    try:
        resp = requests.get(
            f"{GITLAB_URL}/api/v4/projects/{project_id}/members/all",
            headers=_get_gitlab_headers(),
            timeout=10,
        )
        if resp.status_code == 200:
            return resp.json()
    except Exception:
        return []
    return []


def _get_mrs(project_id):
    try:
        resp = requests.get(
            f"{GITLAB_URL}/api/v4/projects/{project_id}/merge_requests",
            params={"state": "all"},
            headers=_get_gitlab_headers(),
            timeout=10,
        )
        if resp.status_code == 200:
            return resp.json()
    except Exception:
        return []
    return []


def _get_file_content(project_id, file_path, ref):
    try:
        from urllib.parse import quote
        encoded = quote(file_path, safe="")
        resp = requests.get(
            f"{GITLAB_URL}/api/v4/projects/{project_id}/repository/files/{encoded}/raw",
            params={"ref": ref},
            headers=_get_gitlab_headers(),
            timeout=10,
        )
        if resp.status_code == 200:
            return resp.text
    except Exception:
        return None
    return None


def _get_rocketchat_legal_messages():
    try:
        if oas_common and hasattr(oas_common, "get_rocketchat_channel_messages"):
            return oas_common.get_rocketchat_channel_messages("legal")
    except Exception:
        pass
    try:
        headers = {}
        token = os.environ.get("ROCKETCHAT_TOKEN")
        user_id = os.environ.get("ROCKETCHAT_USER_ID")
        if token and user_id:
            headers = {"X-Auth-Token": token, "X-User-Id": user_id}
        resp = requests.get(
            f"{ROCKETCHAT_URL}/api/v1/channels.history",
            params={"roomName": "legal", "count": 200},
