    return False


@grader
def check_merge_request_opened():
    project_id = _get_project_id()
    if project_id is None:
        return False
    mrs = _get_mrs(project_id)
    for mr in mrs:
        target = mr.get("target_branch", "")
        title = (mr.get("title") or "").lower()
        desc = (mr.get("description") or "").lower()
